import {colors} from './engine.js';
export function drawWorld(canvas,s,f,e,t){const c=canvas.getContext('2d'),w=1000,h=560;c.clearRect(0,0,w,h);const sky=c.createLinearGradient(0,0,0,h);sky.addColorStop(0,['#192c42','#1d3845','#182937'][s.zone]);sky.addColorStop(1,'#4b777c');c.fillStyle=sky;c.fillRect(0,0,w,h);
const poly=(pts,fill,stroke)=>{c.beginPath();pts.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.stroke();}};
const ellipse=(x,y,rx,ry,color)=>{c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=color;c.fill();};
for(let i=0;i<60;i++){c.globalAlpha=.2+.3*Math.sin(t/2500+i)**2;c.fillStyle='#c6eff0';c.fillRect((i*137)%1000,(i*61)%260,1.5,1.5);}c.globalAlpha=1;ellipse(780,101,33,33,'#c5d6b9');ellipse(765,90,30,30,'#293f50');
for(let i=0;i<18;i++){const x=i*64-20,y=140+(i*37)%90;c.fillStyle=i%2?'#233b4c':'#294455';c.fillRect(x,y,52,220);for(let j=0;j<5;j++)for(let k=0;k<3;k++){c.fillStyle=(i+j+k)%3?'#80b9b131':'#cfbe8666';c.fillRect(x+8+k*14,y+15+j*26,5,11);}}
poly([[0,335],[520,250],[1000,355],[1000,560],[0,560]],'#28414a');for(let i=-3;i<12;i++){c.strokeStyle='#91b5ab13';c.beginPath();c.moveTo(i*120,560);c.lineTo(500+(i-4)*55,285);c.stroke();}for(let i=0;i<7;i++){c.strokeStyle='#a6c4b013';c.beginPath();c.moveTo(0,350+i*34);c.lineTo(1000,350+i*34);c.stroke();}
function house(x,y,bw,bh,col){poly([[x,y],[x+bw,y+35],[x+bw,y+bh+35],[x,y+bh]],col);poly([[x+bw,y+35],[x+bw+55,y+8],[x+bw+55,y+bh+8],[x+bw,y+bh+35]],'#172f3a');poly([[x-12,y-5],[x+50,y-34],[x+bw+65,y+1],[x+bw,y+40]],'#45636a','#78938d55');for(let j=0;j<3;j++)for(let k=0;k<3;k++){c.fillStyle=(j+k)%2?'#e7c88c99':'#8ecfcb55';c.fillRect(x+15+k*(bw-20)/3,y+35+j*(bh-55)/3,18,26);c.fillStyle='#203d43';c.fillRect(x+23+k*(bw-20)/3,y+35+j*(bh-55)/3,2,26);}c.fillStyle='#102932';c.fillRect(x+bw*.43,y+bh-49,29,60);}
if(s.zone===0){house(20,171,180,191,'#38535d');house(225,220,116,120,'#3d6066');house(737,194,155,180,'#365159');house(880,130,110,220,'#2b4352');poly([[35,304],[190,334],[214,351],[22,321]],'#71968c');c.save();c.translate(60,285);c.rotate(.18);c.fillStyle='#c8bd91';c.fillRect(0,0,109,25);c.fillStyle='#2c4546';c.font='bold 12px sans-serif';c.fillText('QUÁN BÀ TƯ',12,17);c.restore();c.strokeStyle='#102a35';c.lineWidth=2;c.beginPath();c.moveTo(0,151);c.quadraticCurveTo(480,350,1000,130);c.stroke();for(let i=0;i<9;i++)ellipse(70+i*103,184+Math.sin(i/9*Math.PI)*54,3,6,'#e2bf78');}
function tree(x,y,size){c.fillStyle='#243c3a';c.fillRect(x-8,y-size*.7,16,size*.7);for(let i=0;i<6;i++)ellipse(x+Math.cos(i*2)*size*.24,y-size*.7+Math.sin(i*2)*size*.18,size*.35,size*.29,['#345b53','#426d60','#537d67'][i%3]);}
if(s.zone===1){for(let i=0;i<6;i++)tree(70+i*173,330+(i%2)*28,120+(i%3)*25);poly([[0,450],[1000,410],[1000,453],[0,490]],'#76948744');ellipse(610,332,100,30,'#80c6a222');}
if(s.zone===2){house(60,200,245,130,'#365463');poly([[610,257],[923,289],[870,455],[567,418]],'#142631','#6c989755');for(let i=0;i<8;i++)poly([[610-i*4,285+i*17],[916-i*5,317+i*17],[909-i*5,322+i*17],[606-i*4,290+i*17]],'#44616b');c.fillStyle='#8dcac3';c.font='18px sans-serif';c.fillText('METRO 09',100,228);ellipse(756,388,85,30,'#6ecbd622');}
// Lanterns, luminous current and foreground foliage create the layered city depth.
for(const x of [365,710]){c.fillStyle='#203c44';c.fillRect(x,242,5,140);c.fillStyle='#ddc38b';c.fillRect(x-11,239,27,16);const g=c.createRadialGradient(x,250,2,x,250,67);g.addColorStop(0,'#e5cf8c44');g.addColorStop(1,'#e5cf8c00');c.fillStyle=g;c.fillRect(x-67,183,134,134);}
c.save();c.strokeStyle='#93e5cf44';c.lineWidth=2;for(let i=0;i<4;i++){c.beginPath();c.ellipse(490,411,90+i*14,27+i*5,-.05,0,Math.PI*2);c.stroke();}c.restore();
function hero(x,y){ellipse(x,y+8,28,9,'#071c2788');const bob=Math.sin(t/600)*3;c.save();c.translate(x,y+bob);c.strokeStyle='#19313b';c.lineWidth=10;c.beginPath();c.moveTo(-8,-21);c.lineTo(-12,2);c.moveTo(8,-21);c.lineTo(13,2);c.stroke();poly([[-18,-63],[14,-63],[26,-18],[0,-25],[-26,-12]],'#c4d9d0','#e9e1c0');poly([[-8,-59],[8,-60],[12,-23],[-12,-23]],'#234552');poly([[14,-54],[22,-51],[37,-33],[29,-28]],'#bccfc8');ellipse(0,-79,15,18,'#e7c5aa');poly([[-16,-77],[-17,-90],[-7,-101],[11,-96],[19,-81],[7,-87],[0,-77],[-3,-88]],'#1a2b3e');c.fillStyle='#283b47';c.fillRect(6,-79,3,2);c.strokeStyle=colors[s.element];c.lineWidth=3;c.beginPath();c.moveTo(33,-35);c.lineTo(52,-86);c.stroke();ellipse(53,-89,6,6,colors[s.element]);c.restore();}
const offset=f?Math.sin(t/160)*3:0;hero(470+offset,405);const py=385+Math.sin(t/400)*5;ellipse(409,py+22,19,6,'#10273188');ellipse(409,py,17,17,colors[s.pet]);poly([[394,py-7],[395,py-24],[405,py-14]],colors[s.pet]);poly([[414,py-13],[424,py-23],[424,py]],colors[s.pet]);ellipse(403,py-1,2,3,'#263e46');ellipse(416,py-1,2,3,'#263e46');
if(f){const x=655,y=400,b=f.boss?1.35:1;c.save();c.translate(x,y);c.scale(b,b);ellipse(0,12,31,10,'#071b2588');if(s.zone===0){poly([[-28,-7],[-35,-45],[-14,-78],[22,-69],[36,-27],[20,1]],'#7f9289','#c0c5a0');poly([[-15,-42],[2,-49],[23,-38],[5,-27]],'#93d2be');}else if(s.zone===1){c.fillStyle='#5e7163';c.fillRect(-20,-65,40,70);for(let i=0;i<5;i++)ellipse(Math.cos(i*2)*26,-68+Math.sin(i*2)*20,24,27,'#719378');}else{ellipse(0,-31,31,42,'#75b9ceaa');ellipse(-10,-52,12,20,'#c0f6ec66');}ellipse(-10,-45,4,3,'#f2b4a0');ellipse(10,-45,4,3,'#f2b4a0');c.restore();}
if(e&&t-e.time<650){const a=(t-e.time)/650;c.globalAlpha=1-a;c.strokeStyle=e.skill?colors[s.element]:'#e6d7ac';c.lineWidth=e.skill?5:2;c.beginPath();c.moveTo(510,350);c.quadraticCurveTo(570,290,655,355);c.stroke();ellipse(655,355,10+a*28,15+a*20,colors[s.element]+'55');c.fillStyle='#fff3cd';c.font='bold 24px sans-serif';c.fillText('-'+e.damage,640,290-a*40);c.globalAlpha=1;}
for(let i=0;i<28;i++){const x=(i*97+t*.012)%1000,y=290+((i*43-t*.018)%240+240)%240;c.globalAlpha=.25+.5*Math.sin(t/800+i)**2;ellipse(x,y,1.6,1.6,'#b9efd8');}c.globalAlpha=1;tree(-20,600,220);tree(1010,600,220);const shade=c.createLinearGradient(0,440,0,560);shade.addColorStop(0,'#0c202900');shade.addColorStop(1,'#0c2029dd');c.fillStyle=shade;c.fillRect(0,440,1000,120);}
